import json

from tasks.storage import load_tasks, tasks_path


def summary() -> str:
    """Сводка по задачам: всего, сделано и осталось."""
    tasks = load_tasks()
    done = sum(1 for task in tasks if task.done)
    return f"всего {len(tasks)}, сделано {done}, осталось {len(tasks) - done}"


